if($path==='/admin/login'){if($method==='POST'&&hash_equals((string)envv('ADMIN_EMAIL',''),(string)($_POST['email']??''))&&password_verify((string)($_POST['password']??''),(string)envv('ADMIN_PASSWORD_HASH',''))){session_regenerate_id(true);$_SESSION['admin_authenticated']=true;header('Location: /admin');exit;}$error=$method==='POST'?'Credenciais inv&aacute;lidas':null;?><!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Entrar | Checkout 360BH</title><link rel="stylesheet" href="/assets/admin.css"></head><body class="login-page"><main class="login-card"><div class="brand">360BH <small>Checkout financeiro</small></div><h1>Acesso administrativo</h1><p class="muted">Gerencie cobran&ccedil;as e links de pagamento.</p><?php if($error):?><div class="error"><?=$error?></div><?php endif;?><form method="post"><div class="field"><label>E-mail</label><input name="email" type="email" required></div><div class="field"><label>Senha</label><input name="password" type="password" required></div><button class="btn">Entrar no painel</button></form></main></body></html><?php exit;}
