if($path==='/admin/services'){if($method==='POST'){csrf_check();$key=public_token();db()->prepare('INSERT INTO services(name,api_key_hash,webhook_url,webhook_secret_hash) VALUES(?,?,?,?)')->execute([trim($_POST['name']),hash('sha256',$key),trim($_POST['webhook_url']??'')?:null,trim($_POST['webhook_secret_hash']??'')?:null]);$createdKey=$key;}$services=db()->query('SELECT id,name,webhook_url,active FROM services ORDER BY id DESC')->fetchAll();admin_layout_start('Servi&ccedil;os','services');?><div class="welcome"><h2>Servi&ccedil;os integrados</h2><p class="muted">Cada servi&ccedil;o recebe uma chave pr&oacute;pria para criar cobran&ccedil;as pela API.</p></div><?php if(isset($createdKey)):?><div class="notice"><strong>Chave criada. Copie agora:</strong><br><code><?=htmlspecialchars($createdKey)?></code><br>Ela n&atilde;o ser&aacute; exibida novamente.</div><?php endif;?><section class="panel"><div class="panel-header"><h2>Cadastrar servi&ccedil;o</h2></div><form method="post"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><div class="form-grid"><div class="field"><label>Nome do servi&ccedil;o *</label><input name="name" required></div><div class="field"><label>URL do webhook</label><input name="webhook_url" type="url"></div><div class="field full"><label>Secret do webhook</label><input name="webhook_secret_hash"></div></div><div class="form-actions"><button class="btn">Cadastrar servi&ccedil;o</button></div></form></section><section class="panel" style="margin-top:20px"><div class="panel-header"><h2>Servi&ccedil;os cadastrados</h2></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Nome</th><th>Webhook</th><th>Status</th></tr></thead><tbody><?php foreach($services as $s):?><tr><td>#<?=$s['id']?></td><td><?=htmlspecialchars($s['name'])?></td><td><?=htmlspecialchars($s['webhook_url']?:'N&atilde;o configurado')?></td><td><span class="status status-active">Ativo</span></td></tr><?php endforeach;?></tbody></table></div></section><?php admin_layout_end();exit;}
if($path==='/admin/customers'){ $error=null;if($method==='POST'){csrf_check();$d=['name'=>trim($_POST['name']??''),'email'=>trim($_POST['email']??''),'cpf'=>preg_replace('/\D+/','',$_POST['cpf_cnpj']??''),'phone'=>preg_replace('/\D+/','',$_POST['phone']??''),'postal'=>preg_replace('/\D+/','',$_POST['postal_code']??''),'address'=>trim($_POST['address']??''),'number'=>trim($_POST['address_number']??''),'complement'=>trim($_POST['complement']??''),'province'=>trim($_POST['province']??''),'city'=>trim($_POST['city']??''),'state'=>trim($_POST['state']??'')];foreach(['name','email','cpf','phone','postal','address','number','province','city','state'] as $f)if($d[$f]==='')$error='Preencha todos os campos obrigat&oacute;rios.';if(!$error){db()->prepare('INSERT INTO customers(name,email,cpf_cnpj,phone,postal_code,address,address_number,complement,province,city,state) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$d['name'],$d['email'],$d['cpf'],$d['phone'],$d['postal'],$d['address'],$d['number'],$d['complement']?:null,$d['province'],$d['city'],$d['state']]);$created=true;}}$customers=db()->query('SELECT id,name,email,cpf_cnpj,phone,city,state,created_at FROM customers ORDER BY id DESC LIMIT 100')->fetchAll();admin_layout_start('Clientes','customers');?><div class="welcome"><h2>Clientes financeiros</h2><p class="muted">Dados preparados para Asaas e Mercado Pago. N&atilde;o armazenamos cart&atilde;o ou CVV.</p></div><?php if(!empty($created)):?><div class="notice">Cliente cadastrado com sucesso.</div><?php endif;if($error):?><div class="error"><?=$error?></div><?php endif;?><section class="panel"><div class="panel-header"><h2>Novo cliente</h2></div><form method="post"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><div class="form-grid"><div class="field"><label>Nome completo *</label><input name="name" required></div><div class="field"><label>E-mail *</label><input name="email" type="email" required></div><div class="field"><label>CPF/CNPJ *</label><input name="cpf_cnpj" required></div><div class="field"><label>Celular com DDD *</label><input name="phone" type="tel" required></div><div class="field"><label>CEP *</label><input name="postal_code" required></div><div class="field"><label>Logradouro *</label><input name="address" required></div><div class="field"><label>N&uacute;mero *</label><input name="address_number" required></div><div class="field"><label>Complemento</label><input name="complement"></div><div class="field"><label>Bairro *</label><input name="province" required></div><div class="field"><label>Cidade *</label><input name="city" required></div><div class="field"><label>Estado *</label><input name="state" maxlength="2" required></div></div><p class="muted">Nome e CPF/CNPJ s&atilde;o exigidos pelo Asaas. Os demais dados melhoram comunica&ccedil;&atilde;o e an&aacute;lise de risco.</p><div class="form-actions"><button class="btn">Cadastrar cliente</button></div></form></section><section class="panel" style="margin-top:20px"><div class="panel-header"><h2>Clientes cadastrados</h2></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Nome</th><th>E-mail</th><th>Documento</th><th>Localidade</th></tr></thead><tbody><?php foreach($customers as $c):?><tr><td>#<?=$c['id']?></td><td><?=htmlspecialchars($c['name'])?></td><td><?=htmlspecialchars($c['email'])?></td><td><?=htmlspecialchars($c['cpf_cnpj'])?></td><td><?=htmlspecialchars($c['city'].'/'.$c['state'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php admin_layout_end();exit;}
if($path==='/admin/links/new'){if($method==='POST'){csrf_check();$raw=public_token();db()->prepare('INSERT INTO payment_links(token_hash,amount_cents,currency,description,payment_type,expires_at,max_uses,created_by) VALUES(?,?,?,?,?,?,?,?)')->execute([token_hash($raw),(int)$_POST['amount_cents'],'BRL',$_POST['description'],$_POST['payment_type'],$_POST['expires_at']?:null,(int)$_POST['max_uses']?:1,envv('ADMIN_EMAIL')]);$url=rtrim((string)envv('APP_URL'),' /').'/pagar/'.$raw;admin_layout_start('Link criado','links');?><div class="panel"><div class="notice">O link foi criado e j&aacute; pode ser enviado ao cliente.</div><p><strong><?=htmlspecialchars($url)?></strong></p><div class="form-actions"><a class="btn" href="<?=htmlspecialchars($url)?>" target="_blank">Abrir checkout</a><a class="btn btn-light" href="/admin">Voltar</a></div></div><?php admin_layout_end();exit;}admin_layout_start('Nova cobran&ccedil;a','links');?><div class="welcome"><h2>Criar link de pagamento</h2><p class="muted">Envie uma cobran&ccedil;a segura sem expor dados do gateway.</p></div><section class="panel"><form method="post"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><div class="form-grid"><div class="field full"><label>Descri&ccedil;&atilde;o *</label><input name="description" required></div><div class="field"><label>Valor em centavos *</label><input name="amount_cents" type="number" min="1" required></div><div class="field"><label>Tipo *</label><select name="payment_type"><option value="ONE_TIME">Pagamento avulso</option><option value="SUBSCRIPTION">Assinatura mensal</option></select></div><div class="field"><label>Expira&ccedil;&atilde;o</label><input name="expires_at" type="datetime-local"></div><div class="field"><label>Limite de utiliza&ccedil;&otilde;es</label><input name="max_uses" type="number" min="1" value="1"></div></div><div class="form-actions"><button class="btn">Gerar link de pagamento</button><a class="btn btn-light" href="/admin">Cancelar</a></div></form></section><?php admin_layout_end();exit;}
if($path==='/admin'){ $pdo=db();$links=$pdo->query('SELECT id,description,amount_cents,payment_type,status,created_at FROM payment_links ORDER BY id DESC LIMIT 50')->fetchAll();$total=(int)$pdo->query('SELECT COUNT(*) FROM payment_links')->fetchColumn();$active=(int)$pdo->query("SELECT COUNT(*) FROM payment_links WHERE status='ACTIVE'")->fetchColumn();$paid=(int)$pdo->query("SELECT COUNT(*) FROM payment_intents WHERE status='PAID'")->fetchColumn();admin_layout_start('Vis&atilde;o geral','dashboard');?><div class="welcome"><h2>Ol&aacute;, administrador</h2><p class="muted">Acompanhe seus links e cobran&ccedil;as em um s&oacute; lugar.</p></div><section class="cards"><div class="card"><div class="card-label">Links criados</div><div class="card-value"><?=$total?></div></div><div class="card"><div class="card-label">Links ativos</div><div class="card-value"><?=$active?></div></div><div class="card"><div class="card-label">Pagamentos aprovados</div><div class="card-value"><?=$paid?></div></div><div class="card"><div class="card-label">Gateway</div><div class="card-value" style="font-size:20px">Asaas</div></div></section><section class="panel"><div class="panel-header"><h2>Links de cobran&ccedil;a recentes</h2><a class="btn" href="/admin/links/new">Criar link</a></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Descri&ccedil;&atilde;o</th><th>Valor</th><th>Tipo</th><th>Status</th><th>Criado em</th></tr></thead><tbody><?php foreach($links as $l):?><tr><td>#<?=$l['id']?></td><td><?=htmlspecialchars($l['description'])?></td><td>R$ <?=money((int)$l['amount_cents'])?></td><td><?=($l['payment_type']==='SUBSCRIPTION'?'Assinatura':'Avulso')?></td><td><span class="status status-<?=strtolower($l['status'])?>"><?=$l['status']?></span></td><td><?=date('d/m/Y H:i',strtotime($l['created_at']))?></td></tr><?php endforeach;?></tbody></table></div></section><?php admin_layout_end();exit;}
